    /// <summary>
    /// This function is like gst_rtcp_packet_sdes_get_entry() but it returns a
    /// null-terminated copy of the data instead. use g_free() after usage.
    /// </summary>
    /// <remarks>
    /// <para>
    /// Mutates this instance; call it on a variable, not on a copy returned by a
    /// property.
    /// </para>
    /// </remarks>
    /// <param name="type">result of the entry type</param>
    /// <param name="data">result entry data</param>
    /// <returns>%TRUE if there was valid data.</returns>
    public bool SdesCopyEntry(out Gst.Rtp.RTCPSDESType type, out byte[]? data)
    {
        int typeNative = default;
        byte lenNative = default;
        nint dataNative = default;
        fixed (Gst.Rtp.RTCPPacket* self = &this)
        {
            int nativeResult = GstRtcpPacketSdesCopyEntry(self, &typeNative, &lenNative, &dataNative);
            type = (Gst.Rtp.RTCPSDESType)typeNative;
            data = null;
            if (dataNative != 0)
            {
                data = new byte[(int)lenNative];
                new System.ReadOnlySpan<byte>((void*)dataNative, (int)lenNative).CopyTo(data);
                Gst.Interop.GMarshal.Free(dataNative);
            }
            return nativeResult != 0;
        }
    }

